int failures = 0;
// Predeclared truth table, independently held by the host; not generated by Claude.
var cases = new (bool rejected, bool request, bool auth, bool expected)[] {
 (false,false,false,true), (false,false,true,true),
 (false,true,false,true), (false,true,true,true),
 (true,false,false,false), (true,false,true,false),
 (true,true,false,false), (true,true,true,true)
};
foreach(var c in cases) {
 bool actual = Guard.CanEnterInterview(c.rejected,c.request,c.auth);
 bool pass = actual == c.expected;
 Console.WriteLine($"{(pass ? "PASS" : "FAIL")} rejected={c.rejected} request={c.request} auth={c.auth} expected={c.expected} actual={actual}");
 if(!pass) failures++;
}
Console.WriteLine($"cases=8 failures={failures}");
return failures == 0 ? 0 : 1;
